def valid_batch(scores):
    return bool(scores) and all(
        type(score) is int and 0 <= score <= 100
        for score in scores
    )

assert not valid_batch([])
assert valid_batch([0, 100])
assert not valid_batch([True])
assert not valid_batch([101])
print('batch logic checked')

